contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure sender is owner (default in setUp)
        // Bound value to avoid overflow issues and ensure meaningful test
        value = bound(value, 0, address(this).balance);

        // Deal funds to contract for sendMoney
        vm.deal(address(c), 1 ether);

        uint256 balanceBefore = address(c).balance;

        // Call sendMoney - it reverts if target cannot receive ETH
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSelector(c.sendMoney.selector, target, value)
        );
        // data not used

        uint256 balanceAfter = address(c).balance;

        // General rule: if sendMoney succeeded, balance decreased by exactly value
        // If it reverted, balance unchanged (the revert reverts the whole call)
        assertTrue(
            (!success && balanceAfter == balanceBefore) ||
            (success && balanceAfter == balanceBefore - value)
        );
    }
}

