pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        // Restrict value to non-zero to ensure actual ether transfer attempt
        vm.assume(value > 0);
        // Give the contract enough balance to cover the call
        vm.deal(address(c), value);

        // Record deposit count before call
        uint256 depositBefore = c.depositsCount();

        // Call sendMoney with a target that will revert (e.g., address with no payable fallback)
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value));

        // General rule: if the call succeeds, deposit count may increase; if it reverts, deposit count must stay the same
        // But the bug makes sendMoney not revert on failure, so we check that a failed call still does not change depositCount
        // We want the reference to always revert on failed call, so success should be false
        // Assert that the call reverted (i.e., success is false) OR deposit count unchanged
        assertTrue(!success || c.depositsCount() == depositBefore);
    }
}

